  c.save();c.beginPath();c.moveTo(44,40);c.lineTo(reach-12,tipY-7);c.lineTo(reach+7,tipY);c.lineTo(reach-12,tipY+8);c.lineTo(44,45);c.closePath();c.fillStyle='#287c78';c.fill();c.strokeStyle='#195b58';c.lineWidth=1.4;c.stroke();c.clip();
  c.strokeStyle='#f4dfa0';c.lineWidth=3;for(let i=43;i<120;i+=13){c.beginPath();c.moveTo(i,31);c.lineTo(i-9,65);c.stroke()}c.restore();
  c.fillStyle='#1d6460';c.beginPath();c.moveTo(40,37);c.lineTo(48,39);c.lineTo(47,46);c.lineTo(40,44);c.closePath();c.fill();
